"""
wayang_hybrid.py - Wayang Kulit Digital (kontrol tangan webcam) dalam SATU file.

Gabungan dari: hybrid.py + index_1.html + mapping_1.js (tampilan halaman tidak diubah).
  * Python membaca webcam + MediaPipe HandLandmarker, lalu mengirim landmark lewat WebSocket.
  * Halaman web (tertanam di file ini) hanya menggambar wayang. Tanpa Node, CDN, atau WASM.
  * Pemetaan tangan -> wayang (mapping_1.js) ikut tertanam di halaman.

Syarat:   pip install mediapipe opencv-python
Berkas    hand_landmarker.task harus ada di folder yang sama (atau pakai --model).

Jalankan:          python wayang_hybrid.py      lalu buka http://localhost:8123 di Chrome / Edge
Uji tanpa kamera:  python wayang_hybrid.py --demo
"""
import argparse
import base64
import hashlib
import json
import math
import os
import socket
import struct
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse

BASE = os.path.dirname(os.path.abspath(__file__))
